terraform {
  required_version = ">= 1.5"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 5.40"
    }
  }

  backend "gcs" {
    bucket = "terraform-state-production"
    prefix = "gke-infrastructure"
  }
}

variable "project_id" {
  description = "GCP Project ID"
  type        = string
  default     = "gke-production"
}

variable "region" {
  description = "Primary region"
  type        = string
  default     = "us-central1"
}

variable "network_name" {
  description = "VPC network name"
  type        = string
  default     = "production-vpc"
}

resource "google_compute_network" "production_vpc" {
  name                    = var.network_name
  project                 = var.project_id
  auto_create_subnetworks = false
  routing_mode            = "GLOBAL"

  delete_default_routes_on_create = true
}

resource "google_compute_subnetwork" "primary_subnet" {
  name          = "gke-primary-subnet"
  project       = var.project_id
  region        = var.region
  network       = google_compute_network.production_vpc.id
  ip_cidr_range = "10.0.0.0/20"

  secondary_ip_range {
    range_name    = "pods-range"
    ip_cidr_range = "10.4.0.0/14"
  }

  secondary_ip_range {
    range_name    = "services-range"
    ip_cidr_range = "10.8.0.0/20"
  }

  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}

resource "google_compute_subnetwork" "eu_subnet" {
  name          = "gke-eu-subnet"
  project       = var.project_id
  region        = "europe-west1"
  network       = google_compute_network.production_vpc.id
  ip_cidr_range = "10.1.0.0/20"

  secondary_ip_range {
    range_name    = "eu-pods-range"
    ip_cidr_range = "10.16.0.0/14"
  }

  secondary_ip_range {
    range_name    = "eu-services-range"
    ip_cidr_range = "10.20.0.0/20"
  }

  private_ip_google_access = true
}

resource "google_compute_firewall" "allow_internal" {
  name          = "allow-internal"
  project       = var.project_id
  network       = google_compute_network.production_vpc.name
  source_ranges = ["10.0.0.0/8"]

  allow {
    protocol = "tcp"
    ports    = ["0-65535"]
  }

  allow {
    protocol = "udp"
    ports    = ["0-65535"]
  }

  allow {
    protocol = "icmp"
  }
}

resource "google_compute_firewall" "allow_health_checks" {
  name          = "allow-health-checks"
  project       = var.project_id
  network       = google_compute_network.production_vpc.name
  source_ranges = ["130.211.0.0/22", "35.191.0.0/16"]

  allow {
    protocol = "tcp"
  }
}

resource "google_compute_router" "production_router" {
  name    = "production-router"
  project = var.project_id
  region  = var.region
  network = google_compute_network.production_vpc.id
}

resource "google_compute_router_nat" "production_nat" {
  name                               = "production-nat"
  project                            = var.project_id
  region                             = var.region
  router                             = google_compute_router.production_router.name
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"

  min_ports_per_vm                 = 1024
  tcp_transient_idle_timeout_sec   = 30
  tcp_established_idle_timeout_sec = 1200
  udp_idle_timeout_sec             = 30
  icmp_idle_timeout_sec            = 30
}

resource "google_kms_key_ring" "gke_keyring" {
  name     = "gke-keyring"
  project  = var.project_id
  location = var.region
}

resource "google_kms_crypto_key" "gke_etcd_key" {
  name     = "gke-etcd-key"
  key_ring = google_kms_key_ring.gke_keyring.id
  purpose  = "ENCRYPT_DECRYPT"

  version_template {
    algorithm        = "GOOGLE_SYMMETRIC_ENCRYPTION"
    protection_level = "HSM"
  }

  rotation_period = "7776000s"

  lifecycle {
    prevent_destroy = true
  }
}

resource "google_kms_crypto_key" "gke_disk_key" {
  name     = "gke-disk-key"
  key_ring = google_kms_key_ring.gke_keyring.id
  purpose  = "ENCRYPT_DECRYPT"

  version_template {
    algorithm        = "GOOGLE_SYMMETRIC_ENCRYPTION"
    protection_level = "HSM"
  }

  rotation_period = "7776000s"
}

resource "google_container_cluster" "production" {
  name     = "prod-gke-cluster"
  project  = var.project_id
  location = var.region

  release_channel {
    channel = "REGULAR"
  }

  network    = google_compute_network.production_vpc.id
  subnetwork = google_compute_subnetwork.primary_subnet.id

  ip_allocation_policy {
    cluster_secondary_range_name  = "pods-range"
    services_secondary_range_name = "services-range"
  }

  private_cluster_config {
    enable_private_endpoint = false
    enable_private_nodes    = true
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  master_authorized_networks_config {
    cidr_blocks {
      cidr_block   = "10.0.0.0/8"
      display_name = "Corporate Network"
    }
    cidr_blocks {
      cidr_block   = "172.16.0.0/12"
      display_name = "VPN Network"
    }
  }

  binary_authorization {
    evaluation_mode = "PROJECT_SINGLETON_POLICY_ENFORCE"
  }

  database_encryption {
    state    = "ENCRYPTED"
    key_name = google_kms_crypto_key.gke_etcd_key.id
  }

  default_snat_status {
    disabled = true
  }

  enable_intranode_visibility = true
  enable_shielded_nodes       = true
  enable_binary_authorization = true
  enable_l4_ilb_subsetting    = true

  network_policy {
    enabled  = true
    provider = "CALICO"
  }

  logging_config {
    enable_components = ["SYSTEM_COMPONENTS", "WORKLOADS"]
  }

  monitoring_config {
    enable_components = ["SYSTEM_COMPONENTS", "WORKLOADS"]
    managed_prometheus {
      enabled = true
    }
  }

  notification_config {
    pubsub {
      enabled = true
      topic   = "projects/${var.project_id}/topics/gke-notifications"
    }
  }

  resource_usage_export_config {
    bigquery_destination {
      dataset_id = "gke_usage_dataset"
    }
    enable_network_egress_metering       = true
    enable_resource_consumption_metering = true
  }

  vertical_pod_autoscaling {
    enabled = true
  }

  addons_config {
    http_load_balancing {
      disabled = false
    }
    horizontal_pod_autoscaling {
      disabled = false
    }
    network_policy_config {
      disabled = false
    }
    gce_persistent_disk_csi_driver_config {
      enabled = true
    }
    gcp_filestore_csi_driver_config {
      enabled = true
    }
    cloudrun_config {
      disabled = true
    }
    dns_cache_config {
      enabled = true
    }
    gateway_api_config {
      enabled = true
    }
    gke_backup_agent_config {
      enabled = true
    }
  }

  workload_identity_config {
    workload_pool = "${var.project_id}.svc.id.goog"
  }

  mesh_certificates {
    enable_certificates = true
  }

  cost_management_config {
    enabled = true
  }

  node_pool {
    name               = "system-pool"
    initial_node_count = 3

    management {
      auto_repair  = true
      auto_upgrade = true
    }

    node_config {
      machine_type = "e2-medium"
      disk_size_gb = 100
      disk_type    = "pd-balanced"
      image_type   = "COS_CONTAINERD"

      shielded_instance_config {
        enable_secure_boot          = true
        enable_integrity_monitoring = true
      }

      workload_metadata_config {
        mode = "GKE_METADATA"
      }

      labels = {
        environment = "production"
        nodepool    = "system"
      }

      taint {
        key    = "CriticalAddonsOnly"
        value  = "true"
        effect = "NO_SCHEDULE"
      }
    }
  }

  lifecycle {
    ignore_changes = [
      node_pool,
    ]
  }

  timeouts {
    create = "60m"
    update = "60m"
    delete = "60m"
  }
}

resource "google_container_node_pool" "compute_pool" {
  name       = "compute-pool"
  project    = var.project_id
  location   = var.region
  cluster    = google_container_cluster.production.name
  node_count = 3

  management {
    auto_repair  = true
    auto_upgrade = true
  }

  autoscaling {
    min_node_count = 3
    max_node_count = 30
  }

  upgrade_settings {
    max_surge       = 3
    max_unavailable = 1
    strategy        = "SURGE"
  }

  node_config {
    machine_type = "n2-standard-8"
    disk_size_gb = 200
    disk_type    = "pd-ssd"
    image_type   = "COS_CONTAINERD"

    shielded_instance_config {
      enable_secure_boot          = true
      enable_integrity_monitoring = true
    }

    workload_metadata_config {
      mode = "GKE_METADATA"
    }

    labels = {
      environment = "production"
      nodepool    = "compute"
    }
  }
}

resource "google_container_node_pool" "high_memory_pool" {
  name       = "high-memory-pool"
  project    = var.project_id
  location   = var.region
  cluster    = google_container_cluster.production.name
  node_count = 2

  management {
    auto_repair  = true
    auto_upgrade = true
  }

  autoscaling {
    min_node_count = 2
    max_node_count = 15
  }

  node_config {
    machine_type = "n2-highmem-16"
    disk_size_gb = 500
    disk_type    = "pd-ssd"
    image_type   = "COS_CONTAINERD"

    labels = {
      environment       = "production"
      nodepool          = "memory-intensive"
      workload-type     = "memory"
    }

    taint {
      key    = "workload"
      value  = "memory"
      effect = "NO_SCHEDULE"
    }
  }
}

resource "google_container_node_pool" "gpu_pool" {
  name       = "gpu-pool"
  project    = var.project_id
  location   = var.region
  cluster    = google_container_cluster.production.name
  node_count = 0

  management {
    auto_repair  = true
    auto_upgrade = true
  }

  autoscaling {
    min_node_count = 0
    max_node_count = 10
  }

  node_config {
    machine_type = "n1-standard-4"
    disk_size_gb = 200
    disk_type    = "pd-ssd"
    image_type   = "COS_CONTAINERD"

    guest_accelerator {
      type  = "nvidia-tesla-t4"
      count = 1
    }

    labels = {
      environment = "production"
      nodepool    = "gpu"
      accelerator = "nvidia"
    }

    taint {
      key    = "nvidia.com/gpu"
      value  = "true"
      effect = "NO_SCHEDULE"
    }
  }
}

output "cluster_name" {
  value = google_container_cluster.production.name
}

output "cluster_endpoint" {
  value = google_container_cluster.production.endpoint
}

output "cluster_ca_certificate" {
  value     = google_container_cluster.production.master_auth[0].cluster_ca_certificate
  sensitive = true
}
